691	    @Override
692	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
693	        HttpHeaders headers = new HttpHeaders();
694	        Visit visit = visitMapper.toVisit(visitFieldsDto);
695	        Pet pet = new Pet();
696	        pet.setId(petId);
697	        visit.setPet(pet);
